    for text in texts:
        got = string_to_int(text)
        shown = repr(text) if len(text) <= 40 else repr(text[:20]) + f"... ({len(text)} characters)"
        assert got == expected and type(got) is int, f"string_to_int({shown}) should be the int {expected}, got {got!r}"
    return True

solution:
def string_to_int(text):
    i = 0
    while i < len(text) and text[i] == " ":
        i += 1

    sign = 1
    if i < len(text) and text[i] in "+-":
        if text[i] == "-":
            sign = -1
        i += 1

    value = 0
    while i < len(text) and "0" <= text[i] <= "9":
        value = value * 10 + (ord(text[i]) - ord("0"))
        if value > 2**31:                      # already beyond both limits: the rest cannot change the clamped result
            break
        i += 1

    return max(-2**31, min(2**31 - 1, sign * value))
